-- Published Namsan Seoul Tower content. Travel information was checked on
-- 2026-10-04 and must be reconfirmed on the operator's website before travel.

do $$
declare
  location_uuid uuid := '00000000-0000-4000-8000-000000000300';
  revision_uuid uuid := '00000000-0000-4000-8000-000000000400';
begin
  values (location_uuid, 'namsan')
  on conflict (slug) do nothing;

  select id into location_uuid from public.locations
  where slug = 'namsan';

  if not exists (
    select 1 from public.location_revisions
    where location_id = location_uuid and status = 'published'
  ) then
      id, location_id, version_number, status, name, korean_name, english_name,
      address, city, region, country, latitude, longitude, location_type,
      short_description, long_description, cover_image_url, cover_image_credit,
      cover_image_source_url, cover_image_alt, hook_media_kind, hook_media_url,
      hook_media_credit, hook_media_source_url, hook_media_alt, hook_title,
      hook_caption, tags, categories, release_status, estimated_duration_minutes,
      display_order, stamp_name, stamp_description, stamp_image_url,
      stamp_image_credit, stamp_image_source_url, stamp_image_alt,
      experience_featured_fact, opening_hours, ticket_price, recommended_duration,
      best_time_to_visit, accessibility_info, travel_official_source_url,
      travel_last_verified_at
    ) values (
      revision_uuid, location_uuid, 1, 'published', 'Tháp Namsan Seoul', '남산서울타워', 'Namsan Seoul Tower',
      '105 Namsangongwon-gil, Yongsan-gu, Seoul 04340', 'Seoul', 'Yongsan-gu', 'Hàn Quốc',
      37.5513, 126.9882, 'Đài quan sát và tháp truyền phát',
      'Biểu tượng của Seoul trên đỉnh núi Namsan, kết hợp tháp phát sóng, đài quan sát và các trải nghiệm ngắm toàn cảnh thành phố.',
      'Namsan Seoul Tower, còn được biết đến là YTN Seoul Tower hoặc N Seoul Tower, đứng trên núi Namsan ở trung tâm Seoul. Công trình kết hợp chức năng truyền phát sóng với đài quan sát dành cho khách tham quan. Từ khu tháp, người học có thể kết nối câu chuyện về phát triển truyền thông Hàn Quốc với cảnh quan đô thị, công viên Namsan và cách một địa danh hiện đại trở thành biểu tượng thành phố. Hành trình giới thiệu lịch sử xây dựng, các không gian quan sát, cách tiếp cận bằng xe buýt, cáp treo hoặc đi bộ, cùng những quy tắc giúp tham quan an toàn và tôn trọng không gian chung.',
      'https://commons.wikimedia.org/wiki/Special:FilePath/N%20Seoul%20Tower%20%2813952097192%29.jpg',
      'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:N_Seoul_Tower_(13952097192).jpg',
      'Namsan Seoul Tower nhìn từ công viên Namsan', 'image',
      'https://commons.wikimedia.org/wiki/Special:FilePath/N%20Seoul%20Tower%20%2813952097192%29.jpg',
      'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:N_Seoul_Tower_(13952097192).jpg',
      'Namsan Seoul Tower trên đỉnh núi Namsan', 'Ngắm Seoul từ ngọn núi trung tâm',
      'Khám phá nơi thiên nhiên Namsan, công nghệ truyền phát và đường chân trời Seoul gặp nhau.',
      array['Seoul', 'Namsan', 'đài quan sát', 'toàn cảnh'], array['Cảnh quan', 'Công nghệ', 'Văn hóa đô thị'], 'released', 120, 2,
      'Dấu ấn toàn cảnh Seoul', 'Dấu mộc dành cho người hoàn thành hành trình khám phá Namsan Seoul Tower.',
      'https://commons.wikimedia.org/wiki/Special:FilePath/N%20Seoul%20Tower%20%2813952097192%29.jpg',
      'Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:N_Seoul_Tower_(13952097192).jpg',
      'Tháp Namsan Seoul dùng làm biểu tượng dấu mộc',
      'Tòa tháp kết hợp truyền phát sóng, quan sát và du lịch trong cùng một công trình trên núi Namsan.',
      '10:00–22:30 ngày thường; 10:00–23:00 cuối tuần và ngày lễ; vào cửa muộn nhất 30 phút trước giờ đóng.',
      'Đài quan sát: người lớn 29.000 KRW, trẻ em 23.000 KRW; kiểm tra giá và ưu đãi mới nhất trước chuyến đi.',
      'Khoảng 2 giờ, chưa gồm thời gian đi cáp treo hoặc đi bộ lên núi.',
      'Cuối chiều để ngắm hoàng hôn và cảnh đêm; đến sớm vào cuối tuần.',
      'Có thang máy, lối tiếp cận, nhà vệ sinh phù hợp và dịch vụ xe lăn hoặc xe đẩy tại quầy thông tin.',
      'https://english.visitseoul.net/attractions/namsan-seoul-tower_/37', '2026-10-04'
    );











  end if;
end;
$$;

